import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/Programmingthinking/22-Who-exactly-is-the-author-of-Dream-of-the-Red-Chamber.html","title":"23-《红楼梦》的作者究竟是谁？","lang":"zh-CN","frontmatter":{"title":"23-《红楼梦》的作者究竟是谁？","icon":"read","date":"2025-04-23T15:19:32.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1745393076000,"updatedTime":1745393076000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"bornforthis@bornforthis.cn","commits":1,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"af07943021cfb3125decea5ffbeee6321dabd9b2","time":1745393076000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"}]},"readingTime":{"minutes":9.23,"words":2768},"filePathRelative":"column/Programmingthinking/22-Who-exactly-is-the-author-of-Dream-of-the-Red-Chamber.md"}`),a={name:`22-Who-exactly-is-the-author-of-Dream-of-the-Red-Chamber.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你好，我是悦创。</p><p>今天，我想带着你用编程思维来分析一个超级大谜题：<strong>《红楼梦》的作者究竟是谁？</strong></p><figure><img src="/assets/3f60c8bf4da1070296a05616d99da4dc-CgBvpMWz.jpg" alt="《红楼梦》插图" tabindex="0" loading="lazy"><figcaption>《红楼梦》插图</figcaption></figure><p>诶，你可能会有疑问了：难道作者不是<strong>曹雪芹</strong>吗？至多再加上一个<strong>高鹗</strong>。我家那本《红楼梦》，封面上写得清清楚楚呢。</p><p>关于这个问题啊，我就得多说两句了，《红楼梦》的作者是谁，这事可没这么简单。</p><p>在四大名著里头，《红楼梦》是<strong>争议</strong>最多的一本，有好多好多人在研究这本书，甚至研究《红楼梦》都成了一个<strong>专门的学科</strong>了。就跟生物学家研究生物、物理学家研究物理一样，研究《红楼梦》的人也有个称号，叫做“<strong>红学家</strong>”。</p><p>《红楼梦》问世有200多年了。在这200多年里，叫得上名的红学家已经出了上百位，你熟悉的<strong>鲁迅</strong>，就算得上是个红学家。不出名的呢，可能有成千上万人。这么多人研究的一个最重要课题，就是：《红楼梦》的作者究竟是谁。</p><figure><img src="/assets/eeb48e1cfad1f977f74eeda6b3271f3c-CZKNWc0n.jpg" alt="鲁迅" tabindex="0" loading="lazy"><figcaption>鲁迅</figcaption></figure><p>有人统计过，红学家们已经给《红楼梦》研究出了65个可能的作者。在这65个人里头，甚至出现了明朝最后一位皇帝<strong>崇祯</strong>，还有清朝的<strong>顺治皇帝</strong>。你看，红学家的脑洞够大的吧，前后脚两个朝代的两个皇帝，竟然都有可能是《红楼梦》的作者。</p><p>怎么会蹦出这么多可能的作者呢？要怪只怪<strong>历史上留下的信息实在是太少了</strong>。</p><p>就比如曹雪芹吧，现在我们连他哪年生、哪年死，长什么样、到底怎么写的《红楼梦》，都不知道。有关他的信息，加起来可能都不到1000字。难怪红学家们要大开脑洞了。</p><p>直到民国时期，才有一位<strong>大学者胡适</strong>，提出了目前的主流观点：<strong>《红楼梦》的120回里，前80回是曹雪芹写的，后40回是高鹗写的。</strong></p><figure><img src="/assets/dd6594ef0d7656f7004b221677ff3998-DzgJvtQU.jpg" alt="胡适" tabindex="0" loading="lazy"><figcaption>胡适</figcaption></figure><p>这个说法是目前最常见的说法，但批评的人也不在少数。直到现在，还是有一些人认为，整本书都是曹雪芹写的，或者干脆认为，曹雪芹、高鹗都不是作者，真正的作者另有其人。</p><p>可是，文学这种事，有什么绝对正确的意见呢？同样一篇文章，可能你觉得很美，但别的同学就不喜欢。</p><p>这就像是<strong>数学考试和语文考试的差别</strong>。数学考试，你错了就是错了，看到考卷上最后的分数，你肯定是心服口服。但是语文就不一样了，凭什么他的作文得了满分，而我就要扣5分呢？我觉得自己的作文就该得满分呀——你是不是也这样想过呢？</p><p>对于红学家来说，也是这样。这又不是数学题，凭什么你说得就对，我说得就不对？所以，他们一直吵个不停，吵架吵得唾沫星子都能淹死人了。</p><p>那么，我们有什么办法劝劝架，让他们不再吵了呢？</p><p>没错，把这个问题转化成数学题不就行了嘛！你还记得咱们前边讲密码的那节课吗？在一门语言里，有的词使用次数高，有的词使用次数低，根据这个信息就能破解密码。同样的，每个作者也都有自己的<strong>文风和写作习惯</strong>，从他的常用词汇里，也能探测出来作者身份的秘密。</p><p>于是，在大概70年前，就有人开始用统计词汇的方法研究《红楼梦》了。比如说，有个叫<strong>潘富俊</strong>的人，他是<strong>植物学专业</strong>的，于是呢，就去<strong>研究《红楼梦》里植物出现的次数</strong>。</p><figure><img src="/assets/012f452da11862e6d3e446d58daf8c62-IfdTeJRF.jpg" alt="《红楼梦》插图" tabindex="0" loading="lazy"><figcaption>《红楼梦》插图</figcaption></figure><p>结果，他发现，在《红楼梦》前80回里，平均每回出现<strong>11种植物</strong>，而后40回呢，平均每回出现的植物突然掉到了<strong>3.8种</strong>。</p><p>诶，这么看来，前80回的作者真可以算得上是个业余植物学家了。而后40回的作者，植物学知识就匮乏得多了。他们绝不可能是同一个人。</p><p>你看，这种说法是不是很有道理呢？它至少说明了，《红楼梦》前后两部分的作者是不一样的。</p><p>可是这样，大家就会满足了吗？并没有。我们前边讲了，还是有很多人不服胡适。有没有可能，《红楼梦》的作者不止2个，而是有3个、4个？说不定，你的爷爷的爷爷的爷爷的爷爷，也掺和了一脚，写了一回呢？当然，这么说肯定是开玩笑的啦。但对于这种千古之谜，真要是胡适说什么我们就听什么，也不是个好主意。</p><p>那怎么办呢？程序员又想出来一个好办法，能够在事先没有任何信息的情况下，推测出来一本书有几个作者。这种办法就是咱们前边讲过的“<strong>聚类分析</strong>”。</p><p>那聚类分析是怎么做的呢？你可以看看音频封面上的这个图。是不是有很多小方块杂乱地摆在上边呢？</p><figure><img src="data:image/png;base64," alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>如果，我们假设每个小方块都代表一支军队，这些小方块就是几个国家的军队布置图。那现在我问你，一共有几个国家呢？</p><p>你肯定会猜3个吧？每个国家的军队一般都驻扎在自己国家的城市附近，它们肯定会凑成一团的。没错，按照小方块之间距离关系，聚类分析就把它们分成了<strong>3个阵营</strong>，分别用红黄蓝表示。这就是聚类分析的基本思想了！</p><figure><img src="data:image/png;base64," alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>同样的，在做《红楼梦》作者分析的时候，程序员先是找出了一些能代表作者写作风格的文字。</p><p>然后通过一个算法，把每一回里有代表性的文字转换成小方块画在图上，最后看画出来的120个小方块里，哪些小方块凑在一起，那这些小方块代表的回数很可能就是同一个作者写的。</p><p>通过这样的方法，程序员最后得到两个结论。</p><p>第一个结论看起来蛮平常的：<strong>前80回跟后40回的确不是同一个作者写的。</strong></p><p>但第二个结论就神奇了！聚类分析发现，前80回里头的<strong>第67回，很可能是前后2个作者共同完成的</strong>。而且呢，后40回里头的第105回，它既不太像是前80回的作者写的，也不太像是后40回的作者写的。它的作者，很可能另有其人！</p><p>你看，聚类分析不光从数据上验证了《红楼梦》前后80回作者不同，而且还提出了另有新作者的观点，是不是很厉害呀！而且这种数据得出的结论让人信服。</p><p>其实，这种聚类分析的方法不光可以用来破解《红楼梦》作者之谜。在生活里同样特别有用。</p><p>我先问问你：你们班来过<strong>插班生</strong>吗？要是一个新面孔突然出现在你们班里，大家肯定都在默默地观察他。你可能会关心：他是个好玩儿的人吗，他会成为你的朋友吗？同样，老师也会关心：这个孩子学习成绩怎么样呀，能不能和其他同学好好相处？</p><p>可是，现在距离考试还远着呢，成绩这事儿谁也说不准。那么，现在就完全没有办法了解他了吗？其实，利用聚类分析，就可以提前猜到这个新面孔的性格、学习成绩，甚至是一些小癖好。</p><p>具体怎么做呢？我提示你一下啊，中国人有句老话：<strong>物以类聚，人以群分。</strong>就是说，同类的东西经常聚在一起，而志同道合的人呢，也经常在一起活动。这就是中国古代的聚类思想。</p><figure><img src="/assets/e2b9f0da8508cab3efd4a3935b3615e4-vuXQzW82.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>听了提示你想到了吗？这个插班生来到了一个陌生的环境，他肯定要交朋友啊。而人类呢，就喜欢跟自己相似的人交朋友，所以，只需等待一个星期，我们看看他跟谁成了朋友，就可以<strong>猜测他的个性和成绩</strong>了。</p><p>比如说，他要是跟你们班里最闹腾的几个人成了好朋友，那他基本上也是个活泼外向的人；要是他跟学习成绩特别好的人成了朋友，那他的成绩大概也不会太差。</p><p>当然了，这种聚类分析的方法虽然说不上100%准确，但要比毫无目的地瞎猜，还是要准多了。</p><p>其实，只要是需要分类的地方，就有聚类分析的用武之地。所以，用聚类分析给《红楼梦》的每一回按照作者分分类，那是再自然不过的了。欢迎你把这一讲分享给小伙伴，让他也感受一下聚类分析的威力。</p><p>下一集，我们再讲一个计算机的超能力：搜索！为啥你在搜索框里随便输一个词，比方说“动画片”，它就会立刻显示出很多动画片呢？计算机到底是怎么做到这一点的，下集就给你揭秘，我们下集见。</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,50)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};